window.__ttsmArticleContent["d396887cd058"] = "<div> <p>Theo thông tin ban đầu, khoảng 10h30 ngày 19/9, xe tải mang biển kiểm soát 60C-738.xx lưu thông theo hướng từ phường Trảng Bom đi Dầu Giây.</p>\n<figure> <img alt=\"1000034765.jpg\" src=\"https://cdn.tienphong.vn/images/mNqMIL0ohOqfb_yhP2L7YRqSPQCMEuLhD_qTmMzNGmeOoxJ-_oZlT878jgG6Shul8Mp-qVYE8YAbWQhCfn8A_g/1000034765.jpg.avif\" title=\"Hiện trường vụ tai nạn (Ảnh: người dân cung cấp)\"/> <figcaption>Hiện trường vụ tai nạn (Ảnh: người dân cung cấp)</figcaption>\n</figure>\n<p>Khi đến khu vực Bưu điện Trảng Bom, xe tải va chạm với xe máy đang do một phụ nữ điều khiển.</p>\n\n<p>Cú va chạm khiến xe máy lao lên dải phân cách, người phụ nữ ngã xuống đường tử vong tại chỗ. Nạn nhân được xác định là chị N.T.T.H. (SN 1991, ngụ Thống Nhất, TP Đồng Nai).</p>\n<p>Nhận được tin báo, lực lượng chức năng đã có mặt tại hiện trường, tổ chức bảo vệ hiện trường, điều tiết giao thông và điều tra nguyên nhân vụ tai nạn.</p>\n<div> <p>Từ đầu tháng 9/2026, TP. Đồng Nai liên tục xảy ra nhiều vụ tai nạn giao thông va chạm xe máy với xe tải khiến ít nhất 5 người chết. Trong đó vụ việc xảy ra ngày 8/9, tại Cổng 11, phường Phước Tân khiến 3 người chết; vụ việc xảy ra ngày 9/9, tại đường Đặng Văn Trơn, phường Trấn Biên khiến 1 người chết, 1 người bị thương.</p>\n</div>\n\n<div> <article> <figure> <a href=\"https://tienphong.vn/khoi-to-vu-xe-ban-tai-gay-tai-nan-lien-hoan-khien-mot-xe-xe-om-tu-vong-post1876862.tpo\" title=\"Khởi tố vụ xe bán tải gây tai nạn liên hoàn khiến một xế xe ôm tử vong \"> <img alt=\"Khởi tố vụ xe bán tải gây tai nạn liên hoàn khiến một xế xe ôm tử vong \" src=\"https://cdn.tienphong.vn/images/ZO9d4nu1FlrKxa9ALJjFsWpUPotP-iUQvzuP77l7Pb-UGILY_V48qM-P1gqm7XPnOd86-f0u4vMnMNwla0QGHQ/2026-09-1613-52.jpg.avif\"/>  </a> </figure> <h2><a href=\"https://tienphong.vn/khoi-to-vu-xe-ban-tai-gay-tai-nan-lien-hoan-khien-mot-xe-xe-om-tu-vong-post1876862.tpo\" title=\"Khởi tố vụ xe bán tải gây tai nạn liên hoàn khiến một xế xe ôm tử vong \"> Khởi tố vụ xe bán tải gây tai nạn liên hoàn khiến một xế xe ôm tử vong </a></h2> </article>\n</div> <div> <article> <figure> <a href=\"https://tienphong.vn/xe-khach-cho-19-nguoi-lat-xuong-muong-thoat-nuoc-tren-quoc-lo-qua-dong-nai-post1876809.tpo\" title=\"Xe khách chở 19 người lật xuống mương thoát nước trên quốc lộ qua Đồng Nai\"> <img alt=\"Xe khách chở 19 người lật xuống mương thoát nước trên quốc lộ qua Đồng Nai\" src=\"https://cdn.tienphong.vn/images/ZO9d4nu1FlrKxa9ALJjFsWpUPotP-iUQvzuP77l7Pb_71UnuxQC-82idSeKAQh7k-b_uzY3a6SbaTfg7eN5dJcT-cCK_HPsL3smWUWCiSYjh6kvTnGlXM7UTo5hd_rY_/2aoboqyzy3ut2dsxmceeve8sz5g9ockdjdrflyey.jpg.avif\"/>  </a> </figure> <h2><a href=\"https://tienphong.vn/xe-khach-cho-19-nguoi-lat-xuong-muong-thoat-nuoc-tren-quoc-lo-qua-dong-nai-post1876809.tpo\" title=\"Xe khách chở 19 người lật xuống mương thoát nước trên quốc lộ qua Đồng Nai\"> Xe khách chở 19 người lật xuống mương thoát nước trên quốc lộ qua Đồng Nai </a></h2> </article>\n</div> <div> <article> <figure> <a href=\"https://tienphong.vn/xe-tai-va-cham-xe-may-cho-ba-hoc-sinh-hai-em-tu-vong-post1876574.tpo\" title=\"Xe tải va chạm xe máy chở ba học sinh, hai em tử vong\"> <img alt=\"Xe tải va chạm xe máy chở ba học sinh, hai em tử vong\" src=\"https://cdn.tienphong.vn/images/4uv0kPuF6xNjpsju-iztBOTDJsHGwcr4sbhOfC43I2NHkw0Dswh7QPuArpreUr5ZQX0BxGCVj5O2Us3V-YtW2Nxt5KO-rLvHExzt6-fxBQY/2aoboqynloxdg3vb57vziarcnc0syicn7uvewmca.jpg.avif\"/>  </a> </figure> <h2><a href=\"https://tienphong.vn/xe-tai-va-cham-xe-may-cho-ba-hoc-sinh-hai-em-tu-vong-post1876574.tpo\" title=\"Xe tải va chạm xe máy chở ba học sinh, hai em tử vong\"> Xe tải va chạm xe máy chở ba học sinh, hai em tử vong </a></h2> </article>\n</div>   </div>";
